class InvoiceService {
  constructor(private pricing: PricingEngine) {}

  createInvoice(order: Order) {
    const total = this.pricing.calculateTotal(order.items);
    this.audit(order.id);
    return { orderId: order.id, total };
  }

  private audit(id: string) { /* simple logging */ }
}

